import csv
import io


def parse_csv(raw_csv: str):
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        strict=False,
    )
    records = list(reader)
    if not records:
        return {"columns": [], "rows": []}

    def nonempty_count(record):
        return sum(bool(value.strip()) for value in record)

    header_index = next(
        (i for i, record in enumerate(records) if nonempty_count(record) >= 2),
        next((i for i, record in enumerate(records) if nonempty_count(record)), None),
    )
    if header_index is None:
        return {"columns": [], "rows": []}

    columns = records[header_index]
    width = len(columns)
    rows = []

    for record in records[header_index + 1:]:
        if len(record) > width and width:
            record = record[:width - 1] + [",".join(record[width - 1:])]
        elif len(record) < width:
            record = record + [""] * (width - len(record))
        rows.append(record)

    return {"columns": columns, "rows": rows}
